"""Thin wrapper around fastText engine."""

import os
import sys
import subprocess
import tempfile

# Try to import the official fasttext Python binding
try:
    import fasttext
    ENGINE = "fasttext-wheel"
    print("Using fasttext-wheel Python binding")
except ImportError:
    try:
        # Try native build from repo
        repo_dir = os.path.dirname(os.path.abspath(__file__))
        fasttext_bin = os.path.join(repo_dir, "repo", "fasttext")
        if os.path.exists(fasttext_bin):
            ENGINE = "native build"
            print("Using native fastText binary")
        else:
            raise ImportError("No fastText binary found")
    except Exception:
        ENGINE = "fallback"
        print("WARNING: No fastText engine available, will use fallback")


def train(input_path, output_path, **kwargs):
    """Train a fastText model."""
    if ENGINE == "fasttext-wheel":
        # fasttext.train_supervised returns a model object
        model = fasttext.train_supervised(input=input_path, **kwargs)
        model.save_model(output_path)
        return model
    elif ENGINE == "native build":
        # Build command line
        cmd = [fasttext_bin, "supervised", "-input", input_path, "-output", output_path]
        for k, v in kwargs.items():
            cmd.extend([f"-{k}", str(v)])
        subprocess.run(cmd, check=True, capture_output=True)
        # Load model via Python binding if available
        if 'fasttext' in sys.modules:
            model = fasttext.load_model(output_path + ".bin")
            return model
        return None
    else:
        raise RuntimeError("No fastText engine available")


def test(model, test_path):
    """Test a fastText model and return (n_samples, precision, recall)."""
    if ENGINE == "fasttext-wheel":
        return model.test(test_path)
    elif ENGINE == "native build":
        cmd = [fasttext_bin, "test", model, test_path]
        result = subprocess.run(cmd, capture_output=True, text=True, check=True)
        # Parse output: "N\tP@1\tR@1"
        lines = result.stdout.strip().split("\n")
        for line in lines:
            if line and not line.startswith("Read"):
                parts = line.split("\t")
                if len(parts) == 3:
                    return (int(parts[0]), float(parts[1]), float(parts[2]))
        raise RuntimeError(f"Could not parse test output: {result.stdout}")
    else:
        raise RuntimeError("No fastText engine available")


def predict(model, test_path, k=1):
    """Predict labels for test file."""
    if ENGINE == "fasttext-wheel":
        return model.predict(test_path, k=k)
    elif ENGINE == "native build":
        cmd = [fasttext_bin, "predict", model, test_path, str(k)]
        result = subprocess.run(cmd, capture_output=True, text=True, check=True)
        return result.stdout
    else:
        raise RuntimeError("No fastText engine available")

