def _filter_kwargs(kwargs):
    """Keep only whitelisted kwargs."""
    return {k: v for k, v in kwargs.items() if k in _WHITELISTED_ARGS}


def train(input_path, output_path, **kwargs):
    """Train a fastText model and save to output_path (without .bin extension)."""
    kwargs = _filter_kwargs(kwargs)
